// Agent 1 result -> { is_fake, reason }. If the AI call failed, the item is
// dropped here and retried next run (it is never rejected because of an error).

function parseJson(text) {
  if (typeof text !== 'string') return null;
  let t = text.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end < start) return null;
  try { return JSON.parse(t.slice(start, end + 1)); } catch (e) { return null; }
}
function minChars(html) {
  return Math.round(plain(html).length * 0.85);
}
function plain(html, max) {
  const t = String(html || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
  return max && t.length > max ? t.slice(0, max) + '…' : t;
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const src = $('Split items').itemMatching(i).json;
  const res = items[i].json;
  const verdict = parseJson(res?.choices?.[0]?.message?.content);
  if (!verdict || typeof verdict.is_fake !== 'boolean') {
    console.log('Fake check failed, will retry next run:', src.source_url, JSON.stringify(res?.error ?? res).slice(0, 300));
    continue;
  }
  let isFake = verdict.is_fake;
  let reason = String(verdict.reason || '');
  if (src.force_real && isFake) {
    isFake = false;
    reason = 'অ্যাডমিন আগে এটাকে সত্য বলে চিহ্নিত করেছেন। AI এর মত ছিল: ' + reason;
  }
  out.push({ json: { news_id: src.news_id, is_fake: isFake, reason }, pairedItem: { item: i } });
}
return out;

